/* <grp.h> for porting Unix sources to OS-9/68k.   The disk has this header already, as DEFS/os9lib/grp.h; this only puts it   where a Unix source looks for it.  A forward rather than a copy, and a   NARROW one on purpose: putting DEFS/os9lib on the include path wholesale   shadows the SDK's own <time.h> with a copy that includes </h0/defs/setsys.h>   by absolute path, which no build here has. */#include <os9lib/grp.h>